log(f"[spectral] lam1(A_abs) = {LAM1:.6f} (Rayleigh {LAMINFO['rayleigh']:.6f}, "
    f"rel spread last 6 {LAMINFO['rel_spread_last6']:.2e})")

# Crofts/Estrada strength normalisation (tick-233 amendment (b)) -------------
